            <!-- Work History Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(1)">Edit</a>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-2">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &mdash;
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <!-- References Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(2)">Edit</a>
                </div>
                @foreach (var reference in _references)
                {
                    <div class="mb-2">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        <small>@reference.Email &bull; @reference.Phone</small>
                    </div>
                }
            </div>

            <!-- Cover Letter Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(3)">Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@_coverLetter</p>
            </div>

            <div class="form-navigation">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
