+        font-size: 0.9rem;
+    }
+
+    .step.active .step-circle {
+        background: #0d6efd;
+        color: white;
+    }
+
+    .step.completed .step-circle {
+        background: #198754;
+        color: white;
+    }
+
+    .step-label {
+        font-size: 0.75rem;
+        margin-top: 0.25rem;
+        text-align: center;
+        max-width: 80px;
+    }
+
+    .step-connector {
+        width: 40px;
+        height: 2px;
+        background: #dee2e6;
+        margin: 0 0.25rem;
+        margin-bottom: 1.2rem;
+    }
+
+    .step-connector.completed {
+        background: #198754;
+    }
+
+    .form-section {
+        max-width: 700px;
+        margin: 0 auto;
+    }
+
+    .form-navigation {
+        display: flex;
+        justify-content: space-between;
+        margin-top: 1.5rem;
+        gap: 1rem;
+    }
+
